-- 000131: email providers -- task 354 catalog expansion (13 -> 56).
--
-- The runtime registry reads these from the embedded seed
-- (crates/unified-core/provider_registry_seed.json); this migration
-- keeps the durable table from 000127 in sync:
--   * five new columns for the task-354 definition fields
--     (smtp_host / smtp_port / smtp_tls preset, http_api JSONB for
--     the generic HTTP adapter, affiliate_url — empty by default,
--     never invented);
--   * updated notes for the 13 existing email providers (free tier
--     + best-for, from the seed JSON);
--   * INSERTs for the 43 new email providers (26 mailbox SMTP
--     presets, 13 dual API/SMTP relays via SMTP, 4 generic HTTP
--     providers), generated by
--     docs/integration/c12_generate_registry_seed_sql.py --ids
--     email:<43 ids>.
-- Ten providers from the user's 65-list are NOT shipped here
-- (no direct single-message send endpoint): Unisender plus the
-- nine campaign/event marketing APIs (MailerLite, Mailchimp
-- marketing, HubSpot, Omnisend, Klaviyo, GetResponse, AWeber,
-- Constant Contact, Moosend) — see
-- docs/integration/EMAIL_PROVIDERS_TASK354.md. Campaign Monitor
-- ships through its Transactional SMTP relay instead.
--
-- No migration has ever run on live PostgreSQL; the ALTERs are
-- additive and the INSERTs are ON CONFLICT DO NOTHING, so a
-- re-run is a no-op.

ALTER TABLE provider_registry_definitions
    ADD COLUMN IF NOT EXISTS smtp_host TEXT,
    ADD COLUMN IF NOT EXISTS smtp_port INTEGER CHECK (smtp_port BETWEEN 1 AND 65535),
    ADD COLUMN IF NOT EXISTS smtp_tls TEXT CHECK (smtp_tls IN ('starttls', 'implicit', 'none')),
    ADD COLUMN IF NOT EXISTS http_api JSONB,
    ADD COLUMN IF NOT EXISTS affiliate_url TEXT;

-- Updated notes for the 13 existing email providers: free tier +
-- best-for prefix, from the seed JSON (task 354).
UPDATE provider_registry_definitions SET notes = 'No provider pricing — your own server. Best for: any SMTP server when you already run one. Direct SMTP delivery to any server: host, port, TLS mode and credentials live on this connection. Port 465 uses implicit TLS, other TLS ports use STARTTLS. SMTP has no webhooks; bounce and complaint handling is not available for this provider.' WHERE family = 'email' AND provider_id = 'smtp';
UPDATE provider_registry_definitions SET notes = 'Free; Gmail daily sending limits apply. Best for: sending from a personal or Google Workspace account over OAuth2. Sends through smtp.gmail.com:587 with OAuth2 (XOAUTH2) — no app passwords. Link the Google account from the connection (OAuth authorize); the access token refreshes automatically. Scope: https://mail.google.com/.' WHERE family = 'email' AND provider_id = 'gmail';
UPDATE provider_registry_definitions SET notes = 'Free. Best for: sending from a Yahoo Mail account over OAuth2. Sends through smtp.mail.yahoo.com:587 with OAuth2 (XOAUTH2). Link the Yahoo account from the connection (OAuth authorize); the access token refreshes automatically. Scope: mail-w.' WHERE family = 'email' AND provider_id = 'yahoo';
UPDATE provider_registry_definitions SET notes = 'Free. Best for: sending from an Outlook, Microsoft 365 or Hotmail account over OAuth2. Sends through smtp.office365.com:587 with OAuth2 (XOAUTH2). Link the Microsoft account from the connection (OAuth authorize); the access token refreshes automatically. Scope: https://outlook.office365.com/SMTP.Send offline_access.' WHERE family = 'email' AND provider_id = 'outlook';
UPDATE provider_registry_definitions SET notes = 'Paid, no free tier. Best for: Mailchimp users who need transactional mail (receipts, password resets) from the same account as their marketing lists. Sending domains must be verified in Mandrill (Settings > Sending Domains); add SPF and DKIM records for the domain before sending bulk mail. Mandrill webhooks are verified with HMAC-SHA1 over the webhook URL plus the sorted POST parameters, using the webhook key. Set webhook_url to the exact public webhook URL.' WHERE family = 'email' AND provider_id = 'mailchimp';
UPDATE provider_registry_definitions SET notes = 'Free 300 emails/day (about 9,000/month). Best for: small senders who want transactional and marketing mail on one free plan. Verify the sender domain in Brevo (Senders & IP > Domains) and add the SPF and DKIM records Brevo shows; unverified senders are limited. Brevo sends no signature; set a webhook_secret on the connection and Brevo must send it back as the X-Webhook-Secret header (configure it in the Brevo webhook URL as a custom header).' WHERE family = 'email' AND provider_id = 'brevo';
UPDATE provider_registry_definitions SET notes = '60-day trial only, then paid. Best for: high-volume senders who need deliverability tooling and a sandbox. Authenticate the sender domain in SendGrid (Settings > Sender Authentication) with SPF and DKIM; single sender verification is enough for low volume. SendGrid Event Webhook signatures use ECDSA verification, which this module does not implement; set a webhook_secret on the connection and require it as the X-Webhook-Secret header instead.' WHERE family = 'email' AND provider_id = 'sendgrid';
UPDATE provider_registry_definitions SET notes = 'Free 100 emails/day. Best for: developers who want a programmable transactional API with sandbox domains. Add and verify the domain in Mailgun (Sending > Domains) with the SPF and DKIM TXT records; sandbox domains only deliver to authorized recipients. Mailgun webhooks are verified with HMAC-SHA256 over timestamp + token, using the webhook signing key (webhook_secret).' WHERE family = 'email' AND provider_id = 'mailgun';
UPDATE provider_registry_definitions SET notes = 'Free 100 emails/month, never expires. Best for: transactional-only sending where deliverability matters most. Verify the sender signature (Sender Signatures) or the whole domain with DKIM in Postmark; every From address must be verified. Postmark sends no signature; set a webhook_secret on the connection and require it as the X-Webhook-Secret header (Postmark supports basic auth on the webhook URL as an alternative).' WHERE family = 'email' AND provider_id = 'postmark';
UPDATE provider_registry_definitions SET notes = 'No free tier. $0.16 per 1,000 emails on the Essentials plan — the default for new accounts since 21 July 2026; accounts already sending can switch to a la carte at $0.10 per 1,000. Best for: high-volume sending inside AWS at the lowest per-email price. Verify the sender identity (email address or domain) in SES; new accounts are in the SES sandbox and can only send to verified addresses until production access is granted. SES endpoints are per-region (email.<region>.amazonaws.com). SES delivers events through SNS, whose signatures need RSA certificate verification, which this module does not implement; set a webhook_secret on the connection and require it as the X-Webhook-Secret header instead.' WHERE family = 'email' AND provider_id = 'ses';
UPDATE provider_registry_definitions SET notes = 'Free 3,000 emails/month (100/day, verified domain required). Best for: developers sending transactional mail from a modern API. Verify the sending domain in Resend (Domains) with SPF and DKIM; unverified accounts can only send to the account owner address. Resend webhooks are Svix-signed and verified with HMAC-SHA256 over the svix id, timestamp and body, using the webhook signing secret (webhook_secret).' WHERE family = 'email' AND provider_id = 'resend';
UPDATE provider_registry_definitions SET notes = 'Free 1,000 emails/month (50/day, no credit card) — now Bird Email. Best for: transactional mail with a generous no-card free tier. Verify the sending domain in SparkPost (Account > Sending Domains) with SPF and DKIM records. SparkPost sends no signature; set a webhook_secret on the connection and require it as the X-Webhook-Secret header.' WHERE family = 'email' AND provider_id = 'sparkpost';
UPDATE provider_registry_definitions SET notes = 'Free (local binary, no provider). Best for: servers with a local MTA where mail never leaves the box. Delivers through the local sendmail binary (/usr/sbin/sendmail or /usr/bin/sendmail), the system default. No credentials needed. The binary must exist on the server; the connection test reports whether it is present.' WHERE family = 'email' AND provider_id = 'sendmail';

-- The 43 new email providers (generated INSERTs).
-- Seed rows generated from crates/unified-core/provider_registry_seed.json (version 1, 43 providers). Do not hand-edit: regenerate instead.
INSERT INTO provider_registry_definitions (family, provider_id, display_name, logo, base_url, sandbox_base_url, api_style, auth_scheme, webhook_signature_header, allowed_hosts, capabilities, currencies, credentials_shape, models, default_model, adapter_kind, smtp_host, smtp_port, smtp_tls, http_api, affiliate_url, needs_endpoint, needs_delegate, notes, builtin) VALUES ('email', 'zoho', 'Zoho Mail', 'email-zoho', 'https://smtp.zoho.com', NULL, NULL, NULL, NULL, '["smtp.zoho.com"]', '{"transactional":true,"bulk":false,"templates":false,"webhooks":false,"tracking":false,"sandbox":false}', '[]', '[{"name":"username","label":"SMTP username","type":"text","required":true,"secret":false,"placeholder":"you@yourdomain.com","description":"SMTP username (usually the full email address)."},{"name":"password","label":"SMTP password","type":"password","required":true,"secret":true,"description":"Zoho account password. Stored encrypted; never shown again."},{"name":"sender_email","label":"Default sender email","type":"email","required":true,"secret":false,"placeholder":"you@yourdomain.com","description":"From address used when a send does not supply its own. Must be verified with the provider."},{"name":"sender_name","label":"Default sender name","type":"text","required":false,"secret":false,"placeholder":"Example News","description":"Display name shown next to the sender email."},{"name":"test_mode","label":"Test mode (sandbox)","type":"boolean","required":false,"secret":false,"description":"When on, mail is accepted by the provider sandbox where one exists, otherwise recorded as a simulated delivery and never sent."}]', '[]', NULL, 'smtp', 'smtp.zoho.com', 465, 'implicit', NULL, NULL, FALSE, FALSE, 'Free Forever plan: 1 domain, 5 users, 5 GB per user. Best for: small teams that want a free business mailbox with their own domain. Sends through smtp.zoho.com:465 (implicit TLS) or :587 (STARTTLS). Enable IMAP/SMTP access in Zoho Mail settings first. Free tier verified Nov 2026.', TRUE) ON CONFLICT (family, provider_id) DO NOTHING;
