INSERT INTO provider_registry_definitions (family, provider_id, display_name, logo, base_url, sandbox_base_url, api_style, auth_scheme, webhook_signature_header, allowed_hosts, capabilities, currencies, credentials_shape, models, default_model, adapter_kind, smtp_host, smtp_port, smtp_tls, http_api, affiliate_url, needs_endpoint, needs_delegate, notes, builtin) VALUES ('email', 'socketlabs', 'SocketLabs', 'email-socketlabs', 'https://smtp.socketlabs.com', NULL, NULL, NULL, NULL, '["smtp.socketlabs.com"]', '{"transactional":true,"bulk":true,"templates":false,"webhooks":false,"tracking":false,"sandbox":false}', '[]', '[{"name":"username","label":"Server ID (SMTP username)","type":"text","required":true,"secret":false,"placeholder":"you@example.com","description":"SocketLabs Server ID — it is the SMTP username."},{"name":"password","label":"API key (SMTP password)","type":"password","required":true,"secret":true,"description":"SocketLabs API key — it is the SMTP password. Stored encrypted; never shown again."},{"name":"sender_email","label":"Default sender email","type":"email","required":true,"secret":false,"placeholder":"news@example.com","description":"From address used when a send does not supply its own. Must be verified with the provider."},{"name":"sender_name","label":"Default sender name","type":"text","required":false,"secret":false,"placeholder":"Example News","description":"Display name shown next to the sender email."},{"name":"test_mode","label":"Test mode (sandbox)","type":"boolean","required":false,"secret":false,"description":"When on, mail is accepted by the provider sandbox where one exists, otherwise recorded as a simulated delivery and never sent."}]', '[]', NULL, 'smtp', 'smtp.socketlabs.com', 587, 'starttls', NULL, NULL, FALSE, FALSE, 'No free plan — first month free (40,000 emails), then from $39.95/month. Best for: high-volume senders who want a dedicated sending platform. Sends through smtp.socketlabs.com:587 (STARTTLS); an HTTP API is also available. Free tier verified Nov 2026.', TRUE) ON CONFLICT (family, provider_id) DO NOTHING;
INSERT INTO provider_registry_definitions (family, provider_id, display_name, logo, base_url, sandbox_base_url, api_style, auth_scheme, webhook_signature_header, allowed_hosts, capabilities, currencies, credentials_shape, models, default_model, adapter_kind, smtp_host, smtp_port, smtp_tls, http_api, affiliate_url, needs_endpoint, needs_delegate, notes, builtin) VALUES ('email', 'pepipost', 'Pepipost / Netcore', 'email-pepipost', 'https://smtp.netcorecloud.net', NULL, NULL, NULL, NULL, '["smtp.netcorecloud.net"]', '{"transactional":true,"bulk":true,"templates":false,"webhooks":false,"tracking":false,"sandbox":false}', '[]', '[{"name":"username","label":"SMTP username","type":"text","required":true,"secret":false,"placeholder":"you@example.com","description":"SMTP username from the Pepipost dashboard."},{"name":"password","label":"SMTP password","type":"password","required":true,"secret":true,"description":"SMTP password from the Pepipost dashboard. Stored encrypted; never shown again."},{"name":"sender_email","label":"Default sender email","type":"email","required":true,"secret":false,"placeholder":"news@example.com","description":"From address used when a send does not supply its own. Must be verified with the provider."},{"name":"sender_name","label":"Default sender name","type":"text","required":false,"secret":false,"placeholder":"Example News","description":"Display name shown next to the sender email."},{"name":"test_mode","label":"Test mode (sandbox)","type":"boolean","required":false,"secret":false,"description":"When on, mail is accepted by the provider sandbox where one exists, otherwise recorded as a simulated delivery and never sent."}]', '[]', NULL, 'smtp', 'smtp.netcorecloud.net', 587, 'starttls', NULL, NULL, FALSE, FALSE, 'Trial only; no published free plan. Best for: high-volume transactional mail from Netcore. Sends through smtp.netcorecloud.net:587 (STARTTLS); an HTTP API is also available. Free tier unverified — check the provider site.', TRUE) ON CONFLICT (family, provider_id) DO NOTHING;
INSERT INTO provider_registry_definitions (family, provider_id, display_name, logo, base_url, sandbox_base_url, api_style, auth_scheme, webhook_signature_header, allowed_hosts, capabilities, currencies, credentials_shape, models, default_model, adapter_kind, smtp_host, smtp_port, smtp_tls, http_api, affiliate_url, needs_endpoint, needs_delegate, notes, builtin) VALUES ('email', 'smtp-com', 'SMTP.com', 'email-smtp-com', 'https://smtp.smtp.com', NULL, NULL, NULL, NULL, '["smtp.smtp.com"]', '{"transactional":true,"bulk":true,"templates":false,"webhooks":false,"tracking":false,"sandbox":false}', '[]', '[{"name":"username","label":"SMTP username","type":"text","required":true,"secret":false,"placeholder":"you@example.com","description":"SMTP username from the SMTP.com dashboard."},{"name":"password","label":"SMTP password","type":"password","required":true,"secret":true,"description":"SMTP password from the SMTP.com dashboard. Stored encrypted; never shown again."},{"name":"sender_email","label":"Default sender email","type":"email","required":true,"secret":false,"placeholder":"news@example.com","description":"From address used when a send does not supply its own. Must be verified with the provider."},{"name":"sender_name","label":"Default sender name","type":"text","required":false,"secret":false,"placeholder":"Example News","description":"Display name shown next to the sender email."},{"name":"test_mode","label":"Test mode (sandbox)","type":"boolean","required":false,"secret":false,"description":"When on, mail is accepted by the provider sandbox where one exists, otherwise recorded as a simulated delivery and never sent."}]', '[]', NULL, 'smtp', 'smtp.smtp.com', 587, 'starttls', NULL, NULL, FALSE, FALSE, 'Paid from $25 per 50,000 emails. Best for: high-volume transactional mail with a simple SMTP relay. Sends through smtp.smtp.com:587 (STARTTLS); an HTTP API is also available. Free tier verified Nov 2026.', TRUE) ON CONFLICT (family, provider_id) DO NOTHING;
INSERT INTO provider_registry_definitions (family, provider_id, display_name, logo, base_url, sandbox_base_url, api_style, auth_scheme, webhook_signature_header, allowed_hosts, capabilities, currencies, credentials_shape, models, default_model, adapter_kind, smtp_host, smtp_port, smtp_tls, http_api, affiliate_url, needs_endpoint, needs_delegate, notes, builtin) VALUES ('email', 'campaign-monitor', 'Campaign Monitor', 'email-campaign-monitor', 'https://smtp.api.createsend.com', NULL, NULL, NULL, NULL, '["smtp.api.createsend.com"]', '{"transactional":true,"bulk":true,"templates":false,"webhooks":false,"tracking":false,"sandbox":false}', '[]', '[{"name":"username","label":"SMTP username (API token)","type":"text","required":true,"secret":false,"description":"Campaign Monitor Transactional SMTP token — the same token goes in both the username and the password fields."},{"name":"password","label":"SMTP password (same API token)","type":"password","required":true,"secret":true,"description":"The same Campaign Monitor Transactional SMTP token as the username. Stored encrypted; never shown again."},{"name":"sender_email","label":"Default sender email","type":"email","required":true,"secret":false,"placeholder":"news@example.com","description":"From address used when a send does not supply its own. Must be verified with the provider."},{"name":"sender_name","label":"Default sender name","type":"text","required":false,"secret":false,"placeholder":"Example News","description":"Display name shown next to the sender email."},{"name":"test_mode","label":"Test mode (sandbox)","type":"boolean","required":false,"secret":false,"description":"When on, mail is accepted by the provider sandbox where one exists, otherwise recorded as a simulated delivery and never sent."}]', '[]', NULL, 'smtp', 'smtp.api.createsend.com', 587, 'starttls', NULL, NULL, FALSE, FALSE, 'Trial only, no free plan (marketing API); the transactional SMTP relay is paid. Best for: sending through Campaign Monitor''s transactional relay with an existing account. Sends through smtp.api.createsend.com:587 (STARTTLS) — username and password are both your SMTP token. Free tier verified Nov 2026.', TRUE) ON CONFLICT (family, provider_id) DO NOTHING;
INSERT INTO provider_registry_definitions (family, provider_id, display_name, logo, base_url, sandbox_base_url, api_style, auth_scheme, webhook_signature_header, allowed_hosts, capabilities, currencies, credentials_shape, models, default_model, adapter_kind, smtp_host, smtp_port, smtp_tls, http_api, affiliate_url, needs_endpoint, needs_delegate, notes, builtin) VALUES ('email', 'plunk', 'Plunk', 'email-plunk', 'https://api.useplunk.com', NULL, NULL, NULL, NULL, '["api.useplunk.com"]', '{"transactional":true,"bulk":false,"templates":false,"webhooks":true,"tracking":false,"sandbox":false}', '[]', '[{"name":"api_key","label":"Secret key","type":"password","required":true,"secret":true,"description":"Plunk secret key (sk_...) from Settings, API Keys. Sent as a Bearer token."},{"name":"sender_email","label":"Default sender email","type":"email","required":true,"secret":false,"placeholder":"news@example.com","description":"From address used when a send does not supply its own. Must be verified with the provider."},{"name":"sender_name","label":"Default sender name","type":"text","required":false,"secret":false,"placeholder":"Example News","description":"Display name shown next to the sender email."},{"name":"webhook_secret","label":"Webhook secret / signing key","type":"password","required":false,"secret":true,"description":"Secret used to verify incoming webhooks from this provider (see the webhook notes for the kind)."},{"name":"test_mode","label":"Test mode (sandbox)","type":"boolean","required":false,"secret":false,"description":"When on, mail is accepted by the provider sandbox where one exists, otherwise recorded as a simulated delivery and never sent."}]', '[]', NULL, 'generic-http', NULL, NULL, NULL, '{"endpoint":"https://api.useplunk.com/v1/send","auth":{"scheme":"bearer","header":"Authorization"},"payload":{"to":"{to}","subject":"{subject}","body":"{body}","from":"{from}","name":"{from_name}","headers":"{deliverability_headers}"},"id_path":null}', NULL, FALSE, FALSE, 'Free plan exists (check the provider site for the current limit). Best for: SaaS transactional mail from an open-source platform (self-hostable). Sends through the Plunk HTTP API (no SMTP relay): POST /v1/send. Free tier unverified — check the provider site.', TRUE) ON CONFLICT (family, provider_id) DO NOTHING;
INSERT INTO provider_registry_definitions (family, provider_id, display_name, logo, base_url, sandbox_base_url, api_style, auth_scheme, webhook_signature_header, allowed_hosts, capabilities, currencies, credentials_shape, models, default_model, adapter_kind, smtp_host, smtp_port, smtp_tls, http_api, affiliate_url, needs_endpoint, needs_delegate, notes, builtin) VALUES ('email', 'courier', 'Courier', 'email-courier', 'https://api.courier.com', NULL, NULL, NULL, NULL, '["api.courier.com"]', '{"transactional":true,"bulk":false,"templates":false,"webhooks":true,"tracking":false,"sandbox":false}', '[]', '[{"name":"api_key","label":"API key","type":"password","required":true,"secret":true,"description":"Courier API key from Settings, API Keys. Sent as a Bearer token."},{"name":"sender_email","label":"Default sender email","type":"email","required":true,"secret":false,"placeholder":"news@example.com","description":"From address used when a send does not supply its own. Must be verified with the provider."},{"name":"sender_name","label":"Default sender name","type":"text","required":false,"secret":false,"placeholder":"Example News","description":"Display name shown next to the sender email."},{"name":"webhook_secret","label":"Webhook secret / signing key","type":"password","required":false,"secret":true,"description":"Secret used to verify incoming webhooks from this provider (see the webhook notes for the kind)."},{"name":"test_mode","label":"Test mode (sandbox)","type":"boolean","required":false,"secret":false,"description":"When on, mail is accepted by the provider sandbox where one exists, otherwise recorded as a simulated delivery and never sent."}]', '[]', NULL, 'generic-http', NULL, NULL, NULL, '{"endpoint":"https://api.courier.com/send","auth":{"scheme":"bearer","header":"Authorization"},"payload":{"message":{"to":{"email":"{to}"},"content":{"title":"{subject}","body":"{body}"},"routing":{"method":"email","channels":["email"]}}},"id_path":"requestId"}', NULL, FALSE, FALSE, 'Free 10,000 sends/month (per third-party comparison Nov 2026 — check the provider site). Best for: routing one notification to email, SMS and push from a single API. Sends through the Courier HTTP API (no SMTP relay): POST /send. Free tier unverified — check the provider site.', TRUE) ON CONFLICT (family, provider_id) DO NOTHING;
INSERT INTO provider_registry_definitions (family, provider_id, display_name, logo, base_url, sandbox_base_url, api_style, auth_scheme, webhook_signature_header, allowed_hosts, capabilities, currencies, credentials_shape, models, default_model, adapter_kind, smtp_host, smtp_port, smtp_tls, http_api, affiliate_url, needs_endpoint, needs_delegate, notes, builtin) VALUES ('email', 'loops', 'Loops', 'email-loops', 'https://app.loops.so', NULL, NULL, NULL, NULL, '["app.loops.so"]', '{"transactional":true,"bulk":false,"templates":true,"webhooks":true,"tracking":false,"sandbox":false}', '[]', '[{"name":"api_key","label":"API key","type":"password","required":true,"secret":true,"description":"Loops API key from Settings, API. Sent as a Bearer token."},{"name":"sender_email","label":"Default sender email","type":"email","required":true,"secret":false,"placeholder":"news@example.com","description":"From address used when a send does not supply its own. Must be verified with the provider."},{"name":"sender_name","label":"Default sender name","type":"text","required":false,"secret":false,"placeholder":"Example News","description":"Display name shown next to the sender email."},{"name":"webhook_secret","label":"Webhook secret / signing key","type":"password","required":false,"secret":true,"description":"Secret used to verify incoming webhooks from this provider (see the webhook notes for the kind)."},{"name":"test_mode","label":"Test mode (sandbox)","type":"boolean","required":false,"secret":false,"description":"When on, mail is accepted by the provider sandbox where one exists, otherwise recorded as a simulated delivery and never sent."}]', '[]', NULL, 'generic-http', NULL, NULL, NULL, '{"endpoint":"https://app.loops.so/api/v1/transactional","auth":{"scheme":"bearer","header":"Authorization"},"payload":{"email":"{to}","transactionalId":"{template_id}","dataVariables":"{variables}"},"id_path":null}', NULL, FALSE, FALSE, 'Free plan: up to 4,000 sends/month to the first 1,000 contacts. Best for: SaaS lifecycle and transactional mail from templates. Sends through the Loops HTTP API (no SMTP relay): POST /api/v1/transactional — template-first, a published transactional template (transactionalId) is required; there is no raw HTML body option. Free tier verified Nov 2026.', TRUE) ON CONFLICT (family, provider_id) DO NOTHING;
INSERT INTO provider_registry_definitions (family, provider_id, display_name, logo, base_url, sandbox_base_url, api_style, auth_scheme, webhook_signature_header, allowed_hosts, capabilities, currencies, credentials_shape, models, default_model, adapter_kind, smtp_host, smtp_port, smtp_tls, http_api, affiliate_url, needs_endpoint, needs_delegate, notes, builtin) VALUES ('email', 'onesignal', 'OneSignal Email', 'email-onesignal', 'https://api.onesignal.com', NULL, NULL, NULL, NULL, '["api.onesignal.com"]', '{"transactional":true,"bulk":false,"templates":false,"webhooks":true,"tracking":false,"sandbox":false}', '[]', '[{"name":"api_key","label":"REST API key","type":"password","required":true,"secret":true,"description":"OneSignal REST API key from Settings, Keys & IDs. Sent as a Basic token."},{"name":"domain","label":"OneSignal App ID","type":"text","required":true,"secret":false,"description":"Your OneSignal App ID (Settings, Keys & IDs); used as app_id in the API payload. Stored in the domain field."},{"name":"sender_email","label":"Default sender email","type":"email","required":true,"secret":false,"placeholder":"news@example.com","description":"From address used when a send does not supply its own. Must be verified with the provider."},{"name":"sender_name","label":"Default sender name","type":"text","required":false,"secret":false,"placeholder":"Example News","description":"Display name shown next to the sender email."},{"name":"webhook_secret","label":"Webhook secret / signing key","type":"password","required":false,"secret":true,"description":"Secret used to verify incoming webhooks from this provider (see the webhook notes for the kind)."},{"name":"test_mode","label":"Test mode (sandbox)","type":"boolean","required":false,"secret":false,"description":"When on, mail is accepted by the provider sandbox where one exists, otherwise recorded as a simulated delivery and never sent."}]', '[]', NULL, 'generic-http', NULL, NULL, NULL, '{"endpoint":"https://api.onesignal.com/notifications","auth":{"scheme":"basic-key","header":"Authorization"},"payload":{"app_id":"{app_id}","include_email_tokens":["{to}"],"email_subject":"{subject}","email_body":"{body}","email_from_name":"{from_name}","email_from_address":"{from}"},"id_path":"id"}', NULL, FALSE, FALSE, 'Free 10,000 emails/month. Best for: apps already using OneSignal for push that want email from the same account. Sends through the OneSignal HTTP API (no SMTP relay): POST /notifications. The OneSignal App ID goes in the domain field. Free tier verified Nov 2026.', TRUE) ON CONFLICT (family, provider_id) DO NOTHING;
